SELECT id, recipe_id AS recipeDbId, food_name, weight, protein, carb, fat, calorie
FROM ingredients
WHERE recipe_id = #{recipeDbId}

SELECT id, recipe_id AS recipeDbId, food_name, weight, protein, carb, fat, calorie FROM ingredients WHERE recipe_id IN
#{recipeDbId}
ORDER BY recipe_id ASC, id ASC
